create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),name text,mobile text unique,email text,role text not null default 'CUSTOMER',status text not null default 'ACTIVE',created_at timestamptz not null default now());
create table if not exists businesses(id uuid primary key default gen_random_uuid(),owner_id uuid references users(id),name text not null,category text,description text,phone text,address text,city text,verification_status text not null default 'DRAFT',active boolean not null default false,created_at timestamptz not null default now());
create table if not exists services(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id) on delete cascade,name text not null,description text,price numeric(12,2),duration_minutes integer,home_service boolean not null default false,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists bookings(id uuid primary key default gen_random_uuid(),customer_id uuid references users(id),business_id uuid references businesses(id),service_id uuid references services(id),booking_date date,booking_time time,customer_address text,total_amount numeric(12,2),payment_status text default 'PENDING',booking_status text default 'REQUESTED',created_at timestamptz not null default now());
